import {bookFinishes,cleanBookFinish} from './book-finish.js';
import {coverOptions,coverExample} from './cover-catalog.js';
import {giftContentPages} from './experience.js';

const examples={
 livro:{occasion:'casamento',label:'Livro',create:'Fazer um livro assim ↗',description:'Uma capa de tecido, fotos e mensagens para folhear. Abra o exemplo aqui e veja o resultado antes de criar o seu.',features:['Capa com textura','Páginas para folhear','Voz e música opcionais']},
 cartao:{occasion:'namorados',label:'Cartão',create:'Fazer um cartão assim ↗',description:'Uma foto na capa e uma dedicatória por dentro. Um cartão que abre e fecha, com o carinho de vocês.',features:['Capa com a sua foto','Uma dedicatória interna','Abre e fecha em 3D']},
 convite:{occasion:'casamento',label:'Convite',create:'Fazer um convite assim ↗',description:'Nomes, data e local em um convite para abrir no celular. Confira a parte interna e experimente a abertura completa.',features:['Nomes, data e local','Mensagem aos convidados','Link e QR Code']},
 stories:{occasion:'namorados',label:'Stories',create:'Fazer Stories assim ↗',description:'Fotos e palavras em telas verticais. Passe pelas cenas aqui ou abra a apresentação como quem recebe.',features:['Telas em 9:16','Fotos com legendas','Áudio e música opcionais']}
};

export function initBookShowcase({onPreview,onCreate,onCatalog}){
 const section=document.createElement('section');section.className='book-showcase section-width';section.id='livros-design';section.setAttribute('aria-labelledby','book-showcase-title');
 section.innerHTML='<div class="book-showcase-copy"><p class="book-showcase-label">Veja antes de criar</p><h2 id="book-showcase-title"><span>O seu mimo pronto.</span><br><span>Abra e veja.</span></h2><div class="showcase-formats" role="group" aria-label="Escolher um exemplo do presente final"></div><p class="book-showcase-intro"></p><div class="showcase-finishes" role="group" aria-label="Experimentar encadernações"></div><p class="showcase-material-name" aria-live="polite"></p><div class="showcase-features"></div><button class="button primary showcase-create"></button><button class="showcase-catalog">Ver outras capas →</button><small>Exemplos digitais com pessoas e histórias fictícias. Personalize com as suas fotos.</small></div><div class="book-showcase-art"><div class="showcase-stage" aria-label="Prévia interativa do presente final" aria-busy="true"><p class="showcase-loading" role="status"><span class="capi-loader" aria-hidden="true"></span><span class="showcase-loading-text">Preparando o exemplo…</span></p></div><div class="showcase-view-controls"><button class="showcase-previous" type="button" hidden>← Anterior</button><button class="showcase-open" type="button">Folhear o exemplo</button><button class="showcase-fit" type="button">Ver inteiro</button><button class="showcase-recipient" type="button">Abrir como quem recebe ↗</button></div><output class="showcase-page-count" aria-live="polite"></output><p class="showcase-view-note"></p></div>';
 document.querySelector('#colecao').before(section);
 const navLink=document.createElement('a');navLink.href='#livros-design';navLink.textContent='Exemplos';document.querySelector('.nav-wrap nav').append(navLink);
 const $=s=>section.querySelector(s),stage=$('.showcase-stage'),loading=$('.showcase-loading');
 let format='livro',material='cocoa',reader=null,canvas=null,currentMount=null,rendererFormat='',opened=false,index=0,busy=true,activated=false,revision=0,queue=Promise.resolve(),disposed=false;
 const cover=()=>({...coverOptions(examples[format].occasion,format)[0],...(format==='livro'?{bookFinish:cleanBookFinish({material,foil:'gold',ribbon:true})}:{})});
 function data(){const example=coverExample(cover()),book=format==='livro',couple=format==='cartao'||format==='stories';const photo=example.photo,other=book?'assets/photo-life-friends.webp':photo;
  return {...example,coverPhoto:photo,recipient:book||format==='convite'?'Lia & Rafa':'Lia',stationeryDesign:{...example.stationeryDesign,title:book?'O começo de tudo.':format==='cartao'?'Ainda bem que é com você.':example.stationeryDesign.title,closing:'Para guardar. Para sempre lembrar.'},appearance:{...example.appearance,scene:'studio'},experience:{...example.experience,sender:'Rafa',sound:'musicbox',letter:'Lia, tem um pedacinho da nossa história em cada foto. Que bom viver tudo isso com você.',reply:false},photos:[{src:photo,caption:couple?'Os nossos dias, do nosso jeito.':'O nosso começo.'},...(book?[{src:other,caption:'Quem faz parte da nossa história.'}]:[])],pages:[{title:'O nosso primeiro capítulo',message:'As melhores histórias começam nos pequenos encontros. Esta é uma lembrança do nosso começo.',photo},{title:'Quem faz parte da nossa história',message:'Os amigos, as conversas e os dias que ficaram na memória. Que venham muitas outras histórias para a gente guardar.',photo:other}]};
 }
 const pageData=(base,at)=>({...base,...giftContentPages(base)[at],coverPhoto:base.coverPhoto,pageTitle:giftContentPages(base)[at].title});
 function controls(){const story=format==='stories',pages=giftContentPages(data());$('.showcase-open').disabled=busy;$('.showcase-fit').hidden=story;$('.showcase-fit').disabled=busy;$('.showcase-previous').hidden=!story&&!(format==='livro'&&opened);$('.showcase-previous').disabled=busy||index===0;
  $('.showcase-open').textContent=story?'Próxima tela →':!opened?(format==='livro'?'Folhear o exemplo':'Abrir por dentro'):format==='livro'&&index<pages.length-1?'Próxima página →':'Ver a capa';
  $('.showcase-page-count').textContent=story?['Capa','Foto','Encerramento'][index]+' · '+(index+1)+' de 3':opened?(format==='livro'?'Página '+(index+1)+' de '+pages.length:'Parte interna'):'A capa';
 }
 function render(){const ex=examples[format];section.dataset.exampleFormat=format;$('.book-showcase-intro').textContent=ex.description;$('.showcase-create').textContent=ex.create;$('.showcase-finishes').hidden=format!=='livro';$('.showcase-material-name').hidden=format!=='livro';$('.showcase-material-name').textContent=bookFinishes[material].label+' · acabamento champagne';$('.showcase-view-note').textContent=format==='stories'?'Passe pelas telas. No presente completo, a pessoa pode tocar para avançar.':'Arraste para girar. Toque para aproximar um detalhe.';$('.showcase-features').replaceChildren(...ex.features.map(text=>{const span=document.createElement('span');span.textContent=text;return span;}));section.querySelectorAll('[data-example-format]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.exampleFormat===format)));section.querySelectorAll('[data-showcase-finish]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.showcaseFinish===material)));controls();}
 async function load(){activated=true;const own=++revision,snapshot=data(),kind=format;busy=true;loading.hidden=false;loading.querySelector('.capi-loader').hidden=false;loading.querySelector('.showcase-loading-text').textContent='Preparando o exemplo…';stage.setAttribute('aria-busy','true');controls();
  queue=queue.catch(()=>{}).then(async()=>{if(disposed||own!==revision)return;let next=null,nextCanvas=null;const mount=document.createElement('div');mount.className='showcase-object-mount';mount.style.visibility='hidden';stage.append(mount);
   try{if(kind==='stories'){const {drawStoryFrame}=await import('./story-design.js');nextCanvas=document.createElement('canvas');nextCanvas.className='showcase-story-canvas';nextCanvas.setAttribute('role','img');nextCanvas.setAttribute('aria-label','Exemplo do Story final');mount.append(nextCanvas);await drawStoryFrame(nextCanvas,snapshot,{kind:'cover'});}else{const {createBook}=await import('./book.js');next=await createBook(mount,snapshot,{onOpenChange:value=>{if(disposed||own!==revision||reader!==next||currentMount!==mount)return;opened=value;controls();}});next.motion(document.body.classList.contains('no-motion'));if(kind==='livro')for(let i=0;i<2;i++)mount.querySelector('canvas').dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft'}));}
    if(disposed||own!==revision){next?.destroy();mount.remove();return;}reader?.destroy();currentMount?.remove();reader=next;canvas=nextCanvas;currentMount=mount;rendererFormat=kind;mount.style.visibility='';stage.classList.toggle('is-stories',kind==='stories');loading.hidden=true;busy=false;stage.setAttribute('aria-busy','false');controls();
   }catch(error){next?.destroy();mount.remove();if(own===revision){busy=false;if(currentMount)currentMount.style.visibility='hidden';loading.querySelector('.capi-loader').hidden=true;loading.querySelector('.showcase-loading-text').textContent='Toque em “Abrir como quem recebe” para conhecer o exemplo.';controls();stage.setAttribute('aria-busy','false');}}
  });return queue;
 }
 async function storyFrame(){const own=revision,{drawStoryFrame}=await import('./story-design.js');if(canvas)await drawStoryFrame(canvas,data(),{kind:index===0?'cover':index===2?'ending':'photo',photoIndex:0,versionCheck:()=>own===revision});}
 async function advance(delta=1){if(busy)return;await queue;if(rendererFormat!==format)return;const own=revision;busy=true;controls();try{if(format==='stories'){index=(index+delta+3)%3;await storyFrame();}else if(delta<0){const next=Math.max(0,index-1);if(next!==index&&await reader.turn(pageData(data(),next),-1)!==false&&own===revision)index=next;}else if(!opened){await reader.setArtwork(pageData(data(),0));if(own!==revision)return;reader.open(true);opened=true;index=0;}else if(format==='livro'&&index<giftContentPages(data()).length-1){const next=index+1;if(await reader.turn(pageData(data(),next),1)!==false&&own===revision)index=next;}else{reader.open(false);opened=false;index=0;}}
  finally{if(own===revision){busy=false;controls();}}
 }
 for(const [id,ex]of Object.entries(examples)){const button=document.createElement('button');button.type='button';button.dataset.exampleFormat=id;button.textContent=ex.label;button.addEventListener('click',()=>{if(format===id)return;format=id;index=0;opened=false;render();load();});$('.showcase-formats').append(button);}
 for(const [id,finish]of Object.entries(bookFinishes)){const button=document.createElement('button');button.type='button';button.dataset.showcaseFinish=id;button.setAttribute('aria-label','Experimentar '+finish.label);button.style.setProperty('--finish-color',finish.color);button.style.setProperty('--finish-texture','url(assets/book-'+finish.kind+'-albedo.webp)');button.innerHTML='<span></span>';button.addEventListener('click',()=>{material=id;index=0;opened=false;render();load();});$('.showcase-finishes').append(button);}
 const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){if(!activated)load();observer.disconnect();}},{rootMargin:'150px'});observer.observe(section);
 $('.showcase-open').addEventListener('click',()=>advance());$('.showcase-previous').addEventListener('click',()=>advance(-1));$('.showcase-fit').addEventListener('click',()=>reader?.resetView());$('.showcase-recipient').addEventListener('click',()=>onPreview(data()));$('.showcase-create').addEventListener('click',()=>onCreate(cover()));$('.showcase-catalog').addEventListener('click',()=>onCatalog(examples[format].occasion,format));document.querySelector('#motion-toggle')?.addEventListener('click',()=>reader?.motion(document.body.classList.contains('no-motion')));
 addEventListener('pagehide',()=>{disposed=true;revision++;observer.disconnect();reader?.destroy();},{once:true});
 render();window.__bookShowcase={snapshot:()=>format==='stories'?{format:'stories',canvasWidth:canvas?.width,index}:reader?.snapshot(),getData:data,state:()=>({format,rendererFormat,busy,index,opened})};return {section};
}
